theorem abs_coord_sub_le_rho {n k : ℕ} {pts pts' : ℕ → Pt n} {p : ℕ} {i : Fin n}
    (hp : p < k) :
    |pts p i - pts' p i| ≤ rho n k pts pts'

theorem Gated.mul {f₁ g₁ h₁ f₂ g₂ h₂ : ℝ → ℝ}
    (hf₁ : Gated f₁ g₁ h₁) (hf₂ : Gated f₂ g₂ h₂) :
    Gated (fun x => f₁ x * f₂ x) (fun x => g₁ x * g₂ x) (fun x => h₁ x * h₂ x)

theorem layerscale_lipschitz {lam L : ℝ} (_hL : 0 ≤ L) {f : ℝ → ℝ}
    (hf : ∀ x y, |f x - f y| ≤ L * |x - y|) (x y : ℝ) :
    |layerScale lam f x - layerScale lam f y| ≤ (1 + |lam| * L) * |x - y|
